pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 amount) public {
        vm.assume(from != address(0) && from != address(this));
        address[] memory tos = new address[](1);
        tos[0] = address(new Reverter());
        uint[] memory vs = new uint[](1);
        vs[0] = amount;
        bool ok;
        try c.transfer(from, tos[0], tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
